WITH UserActivity AS (SELECT U.Id AS UserId, U.DisplayName, COUNT(DISTINCT P.Id) AS PostCount, SUM(COALESCE(P.ViewCount, 0)) AS TotalViews, SUM(CASE WHEN V.VoteTypeId = 2 THEN 1 ELSE 0 END) AS Upvotes, SUM(CASE WHEN V.VoteTypeId = 3 THEN 1 ELSE 0 END) AS Downvotes, RANK() OVER (ORDER BY COUNT(DISTINCT P.Id) DESC NULLS FIRST) AS PostRank FROM Users AS U LEFT JOIN Posts AS P ON U.Id = P.OwnerUserId LEFT JOIN Votes AS V ON P.Id = V.PostId GROUP BY U.Id, U.DisplayName), TopUsers AS (SELECT UserId, DisplayName, PostCount, TotalViews, Upvotes, Downvotes FROM UserActivity WHERE PostRank <= 10) SELECT TU.DisplayName, TU.PostCount, TU.TotalViews, TU.Upvotes, TU.Downvotes, (TU.Upvotes - TU.Downvotes) AS VoteBalance, (SELECT COUNT(*) FROM Comments AS C WHERE C.UserId = TU.UserId) AS CommentCount, (SELECT COUNT(*) FROM Badges AS B WHERE B.UserId = TU.UserId AND B.Class = 1) AS GoldBadgeCount, COALESCE((SELECT GROUP_CONCAT(T.TagName, ', ') FROM Posts AS P JOIN Tags AS T ON T.ExcerptPostId = P.Id WHERE P.OwnerUserId = TU.UserId), 'No Tags') AS Tags FROM TopUsers AS TU ORDER BY TU.TotalViews DESC NULLS FIRST, TU.DisplayName ASC